-- The update's trigger reloaded the entries it touched; these are the rest.
select lex.gloss_terms_reload(array(
  select distinct s.entry_id from lex.senses s
  where s.gloss_en ~* '^(past participle|present participle|simple past( and past participle)?|gerund|(feminine|masculine)( singular| plural)?|(first|second|third)-person[a-z /-]*) of\M'));

